// https://iquilezles.org/articles/distfunctions2d/
float star(vec2 p, float r, float rf) {
    vec2 k1 = vec2(0.809016994375, -0.587785252292);
    vec2 k2 = vec2(-k1.x, k1.y);

    p.x = abs(p.x);

    p -= 2.0 * max(dot(k1, p), 0.0) * k1;
    p -= 2.0 * max(dot(k2, p), 0.0) * k2;

    p.x  = abs(p.x);
    p.y -= r;

    vec2  ba = rf * vec2(-k1.y, k1.x) - vec2(0.0, 1.0);
    float h  = clamp(dot(p, ba) / dot(ba, ba), 0.0, r);
    return length(p - ba * h) * sign(p.y * ba.x - p.x * ba.y);
}
float rect(vec2 p, vec2 b)
{
    vec2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

float circle(vec2 p, float r) {
    return length(p) - r;
}

// https://github.com/glslify/glsl-aastep
float alpha(float v) {
    float w = length(vec2(dFdx(v), dFdy(v))) * 0.70710678118654757;
    return 1.0 - smoothstep(-w, +w, v);
}

// https://agatedragon.blog/2024/03/06/shadertoy-checkerboard-pattern/
float checkerboard(vec2 uv, vec2 total) {
    float x = floor(total.x * uv.x);
    float y = floor(total.y * uv.y);
    return mod(x + y, 2.0);
}

// https://easings.net/#easeInOutElastic
float ease(float x) {
    float c5 = 6.28318530 / 4.5;

    return x == 0.0
      ? 0.0
      : x == 1.0
      ? 1.0
      : x < 0.5
      ? -(pow(2.0,  20.0 * x - 10.0) * sin((20.0 * x - 11.125) * c5)) / 2.0
      :  (pow(2.0, -20.0 * x + 10.0) * sin((20.0 * x - 11.125) * c5)) / 2.0 + 1.0;
}

vec2 distort(vec2 p, vec2 k) {
    float r  = length(p);
    float th = atan(p.y, p.x);
    float rd = r * (1.0 + k.x * cos(2.0 * th) + k.y * sin(2.0 * th));

    return vec2(cos(th), sin(th)) * rd;
}

void mainImage(out vec4 fragColor, vec2 fragCoord) {
    // Mouse fix.
    vec2  m = (iMouse.z == 0.0 && iMouse.w == 0.0) ? iResolution.xy * 0.5 : iMouse.xy; 

    // Distortion.
    float kmax = 0.2;
    vec2  k    = m / iResolution.xy;

    vec2  p = (2.0 * fragCoord - iResolution.xy) / iResolution.y;
    vec2  q = distort(p, k * 2.0 * kmax - kmax);

    // Shapes' SDFs.
    float ds[3] = float[3](
        star  (q, 0.75, 0.5),
        rect  (q, vec2(0.5)),
        circle(q, 0.5      )
    );

    // Shape interpolation.
    float t = mod(iTime, 9.0);
    float l = ease(fract(iTime));
    float d;
    if      (t < 2.0) d =     ds[0];
    else if (t < 3.0) d = mix(ds[0], ds[1], l);
    else if (t < 5.0) d =     ds[1];
    else if (t < 6.0) d = mix(ds[1], ds[2], l);
    else if (t < 8.0) d =     ds[2];
    else              d = mix(ds[2], ds[0], l);

    // Top-right "display".
    float s = 0.2;
    vec2  u = p - vec2(iResolution.x / iResolution.y , 1.0) + s + 0.05;
    vec2  w = u + k * s * -2.0 + s;

    vec3 c = vec3(0.0);
    c = mix(c, vec3(mix(vec3(0.8), vec3(0.7), checkerboard(u, vec2(25.0)))), alpha(rect(u, vec2(s))));
    c = mix(c, vec3(mix(vec3(0.8), vec3(0.7), checkerboard(u, vec2( 5.0)))), alpha(rect(u, vec2(s))) * 0.6);
    c = mix(c, vec3(0.3), alpha(circle(w, 0.025)));
    c = mix(c, vec3(1.0, 0.0, 0.0), alpha(circle(w, 0.02)));
    c = mix(c, vec3(1.0), alpha(d));


    fragColor = vec4(c, 1.0);
}
